import java.io.*;
import java.util.*;

public class Main {

    // 快速输入，适合本题较大的数据范围
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + c - '0';
                c = read();
            }
            return val * sign;
        }
    }

    // 求整数数组 arr 的最长奇回文半径
    static int oddManacher(int[] arr, int n) {
        int[] d = new int[n];
        int l = 0, r = -1;
        int ans = 0;

        for (int i = 0; i < n; i++) {
            int k;

            // 初始化当前位置的半径
            if (i > r) {
                k = 1;
            } else {
                k = Math.min(d[l + r - i], r - i + 1);
            }

            // 向两边扩展
            while (i - k >= 0 && i + k < n && arr[i - k] == arr[i + k]) {
                k++;
            }

            d[i] = k;
            ans = Math.max(ans, k);

            // 更新当前最右回文区间
            if (i + k - 1 > r) {
                l = i - k + 1;
                r = i + k - 1;
            }
        }

        return ans;
    }

    static int solveOne(int n, int[] c) {
        int[] stack = new int[n];
        int top = 0;

        // 用栈模拟原序列的全部消除
        for (int i = 0; i < n; i++) {
            if (top > 0 && stack[top - 1] == c[i]) {
                top--;
            } else {
                stack[top++] = c[i];
            }
        }

        int m = top;

        // 原本已经可以消除的次数
        int base = (n - m) / 2;

        // 若已经全部消完，插入一个物品也不能产生新消除
        if (m == 0) {
            return base;
        }

        int[] reduced = Arrays.copyOf(stack, m);

        // 插入一次带来的最大额外消除次数
        int extra = oddManacher(reduced, m);

        return base + extra;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        StringBuilder sb = new StringBuilder();

        int T = fs.nextInt();

        for (int tc = 0; tc < T; tc++) {
            int n = fs.nextInt();
            int[] c = new int[n];

            for (int i = 0; i < n; i++) {
                c[i] = fs.nextInt();
            }

            sb.append(solveOne(n, c)).append('\n');
        }

        System.out.print(sb.toString());
    }
}
