}

int solveOne(int n, const vector<int>& c) {
    vector<int> st;

    // 用栈模拟原序列的全部消除
    for (int x : c) {
        if (!st.empty() && st.back() == x) {
            st.pop_back();
        } else {
            st.push_back(x);
